stageCss:
#stage .nh-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .nh-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .nh-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(240,166,74,.14); border:1.5px solid rgba(240,166,74,.42); color:var(--warn);
}
#stage .nh-mark svg{ width:25px; height:25px; }
#stage .nh-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .nh-sent{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .nh-sent b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .nh-sent.ok b{ color:var(--success); }
#stage .nh-sent.bad b{ color:var(--danger); }
#stage .nh-sent i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .nh-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .nh-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .nh-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .nh-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .nh-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .nh-health.warn b{ color:var(--warn); }
#stage .nh-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .nh-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .nh-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .nh-body{ position:relative; flex:1; min-height:0; }
#stage .nh-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .nh-sc.on{ opacity:1; transform:none; }
#stage .nh-sc.whip{ animation:nh-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .nh-loop, #stage .nh-hub{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* -------------------------------------------------------------- campaign -- */
#stage .nh-camp{
  height:120px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .nh-camp.tight{ height:110px; }
#stage .nh-camp.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 46px rgba(63,185,80,.14); }
#stage .nh-camp.bad{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.22), 0 0 46px rgba(244,74,106,.16); }
#stage .nh-camp-ic{
  width:56px; height:56px; border-radius:16px; flex-shrink:0; font-size:28px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .nh-camp-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .nh-camp-t b{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .nh-camp-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .nh-camp-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .nh-camp-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .nh-camp-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

/* ------------------------------------------------------------- platforms -- */
#stage .nh-plats{ height:210px; flex-shrink:0; display:flex; gap:12px; }
#stage .nh-outs{ flex:1; min-height:0; display:flex; align-items:center; gap:12px; }
#stage .nh-plat, #stage .nh-out{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:10px; justify-content:center;
  padding:16px 18px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .nh-plat.hot, #stage .nh-out.hot{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.2), 0 0 40px rgba(240,166,74,.12); }
#stage .nh-out{ height:186px; }
#stage .nh-out.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 40px rgba(63,185,80,.12); }
#stage .nh-plat-h{ display:flex; align-items:center; gap:11px; }
#stage .nh-plat-ic{ font-size:25px; flex-shrink:0; }
#stage .nh-plat-h b{ color:#fff; font-family:var(--font-mono); font-size:22px; font-weight:700; }
#stage .nh-plat-s, #stage .nh-out-s{
  color:var(--text-dim); font-family:var(--font-mono); font-size:17px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .nh-plat-n, #stage .nh-out-n{
  color:#fff; font-family:var(--font-mono); font-size:26px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .nh-out.ok .nh-out-n{ color:var(--success); }

/* ------------------------------------------------------------------ code -- */
#stage .nh-code{
  height:180px; flex-shrink:0; display:flex; flex-direction:column; gap:4px; justify-content:center;
  padding:14px 20px; border-radius:20px;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .nh-code.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.06); }
#stage .nh-code-l{
  color:var(--code-plain); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  transition:color .3s ease;
}
#stage .nh-code-l.hot{ color:var(--warn); }
#stage .nh-code-l.bad{ color:var(--danger); }

/* -------------------------------------------------------------- progress -- */
#stage .nh-prog{
  flex:1; min-height:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:18px 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .nh-prog.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 50px rgba(244,74,106,.18);
  animation:nh-alert 1s ease-in-out infinite;
}
#stage .nh-prog-h{ display:flex; align-items:center; gap:14px; }
#stage .nh-prog-n{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .nh-prog-b{
  margin-left:auto; padding:8px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger);
  font-family:var(--font-mono); font-size:19px; font-weight:800;
}
#stage .nh-meter{ height:20px; border-radius:10px; background:rgba(35,44,64,.9); overflow:hidden; }
#stage .nh-meter i{
  display:block; height:100%; width:2%; border-radius:10px;
  background:linear-gradient(90deg,#F0A64A,#F4C46A);
  transition:width .5s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .nh-meter i.ok{ background:linear-gradient(90deg,#3fb950,#7ee08a); }
#stage .nh-prog-f{
  display:flex; align-items:center; justify-content:space-between;
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
}
#stage .nh-prog-f span:last-child{ color:var(--danger); }

/* ============================ SCENE 2 · THE HUB ======================== */
#stage .nh-hubbox{
  height:168px; flex-shrink:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.5);
  box-shadow:0 0 0 1px rgba(58,160,255,.18), 0 0 60px rgba(58,160,255,.12);
}
#stage .nh-hub-h{ display:flex; align-items:center; gap:14px; }
#stage .nh-hub-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.4);
}
#stage .nh-hub-n{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .nh-hub-b{
  margin-left:auto; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .nh-tags{ display:flex; align-items:center; gap:10px; }
#stage .nh-tag{
  padding:8px 14px; border-radius:10px; white-space:nowrap;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .nh-tag.on{ background:rgba(34,211,238,.18); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }
#stage .nh-expr{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:17px; font-weight:600; white-space:nowrap; transition:color .3s ease;
}
#stage .nh-expr.hot{ color:var(--accent-cyan); }

#stage .nh-fan{
  position:relative; flex-shrink:0; height:62px;
  display:flex; align-items:center; justify-content:flex-start; gap:56px; padding-left:96px;
}
#stage .nh-fan i{
  display:block; width:4px; height:30px; border-radius:2px;
  background:linear-gradient(180deg, rgba(58,160,255,.15), var(--accent-1));
  box-shadow:0 0 12px rgba(58,160,255,.5);
  animation:nh-drop 1.1s linear infinite;
}
#stage .nh-fan i:nth-child(2){ animation-delay:.24s; }
#stage .nh-fan i:nth-child(3){ animation-delay:.48s; }
#stage .nh-fan-t{
  position:absolute; right:20px; top:50%; transform:translateY(-50%);
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; white-space:nowrap;
}

#stage .nh-feed{
  height:96px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:20px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.34; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease;
}
#stage .nh-feed.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(63,185,80,.5);
  background:rgba(63,185,80,.07);
}
#stage .nh-feed-ic{
  width:44px; height:44px; border-radius:13px; flex-shrink:0; font-size:23px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.12); border:1.5px solid rgba(63,185,80,.3);
}
#stage .nh-feed-n{ color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700; white-space:nowrap; }
#stage .nh-feed-s{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:18px; font-weight:600; white-space:nowrap;
}

#stage .nh-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .nh-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .nh-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .nh-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .nh-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .nh-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .nh-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ========================= SCENE 3 · WHO DOES WHAT ===================== */
#stage .nh-split{ display:flex; gap:16px; height:100%; }
#stage .nh-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:26px 18px; border-radius:28px; text-align:center;
}
#stage .nh-col.bad{
  background:radial-gradient(circle at 50% 0%, rgba(244,74,106,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(244,74,106,.5);
}
#stage .nh-col.good{
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.6);
  box-shadow:0 0 0 1px rgba(58,160,255,.2), 0 0 60px rgba(58,160,255,.14);
}
#stage .nh-col-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.4px; white-space:nowrap; }
#stage .nh-col.bad .nh-col-h{ color:var(--danger); }
#stage .nh-col.good .nh-col-h{ color:var(--accent-1); }
#stage .nh-col-ic{ font-size:56px; line-height:1; }
#stage .nh-col.bad .nh-col-ic{ animation:msd-spin 3s linear infinite; }
#stage .nh-col.good .nh-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .nh-col-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .nh-row{
  padding:13px 10px; border-radius:13px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:20px; font-weight:600; line-height:1.25;
}
#stage .nh-row b{ color:var(--text-primary); font-weight:800; }
#stage .nh-col.good .nh-row b{ color:#fff; }
#stage .nh-col-x{
  width:100%; padding:13px 10px; border-radius:14px;
  background:rgba(244,74,106,.14); border:1.5px solid rgba(244,74,106,.5); color:var(--danger);
  font-family:var(--font-mono); font-size:18px; font-weight:700; line-height:1.3;
}
#stage .nh-col-x.ok{ background:rgba(58,160,255,.14); border-color:rgba(58,160,255,.5); color:var(--accent-1); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .nh-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .nh-badge{
  width:132px; height:132px; border-radius:36px; font-size:64px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.28), rgba(34,211,238,.14));
  border:2px solid rgba(58,160,255,.6);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 80px rgba(58,160,255,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .nh-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:21px; font-weight:800; letter-spacing:4px; }
#stage .nh-fin-h{ color:#fff; font-size:64px; font-weight:900; line-height:1.12; letter-spacing:-2px; }
#stage .nh-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .nh-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .nh-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .nh-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:850px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .nh-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes nh-drop{
  0%{ transform:translateY(-16px); opacity:0; }
  25%{ opacity:1; }
  100%{ transform:translateY(20px); opacity:0; }
}
@keyframes nh-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes nh-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

